// The built-in themes (`themes/builtin/*.json`, generated by scripts/gen-builtin-themes.mjs).

import aurora from '../../themes/builtin/aurora.json';
import catppuccinLatte from '../../themes/builtin/catppuccin-latte.json';
import catppuccinMocha from '../../themes/builtin/catppuccin-mocha.json';
import graphite from '../../themes/builtin/graphite.json';
import highContrastDark from '../../themes/builtin/high-contrast-dark.json';
import highContrastLight from '../../themes/builtin/high-contrast-light.json';
import midnight from '../../themes/builtin/midnight.json';
import nord from '../../themes/builtin/nord.json';
import nordLight from '../../themes/builtin/nord-light.json';
import paper from '../../themes/builtin/paper.json';
import solarizedDark from '../../themes/builtin/solarized-dark.json';
import solarizedLight from '../../themes/builtin/solarized-light.json';

import { parseTheme } from './resolve';
import type { ThemeFile } from './types';

/** Every built-in theme, validated; aurora (light) and midnight (dark) are the defaults. */
export const builtinThemes: readonly ThemeFile[] = [
  aurora, midnight, graphite, paper, nord, nordLight,
  catppuccinMocha, catppuccinLatte, solarizedDark, solarizedLight,
  highContrastLight, highContrastDark,
].map((t) => parseTheme(t));

export const DEFAULT_LIGHT_THEME = 'aurora';
export const DEFAULT_DARK_THEME = 'midnight';

/** A built-in theme by id. */
export function builtinTheme(id: string): ThemeFile | undefined {
  return builtinThemes.find((t) => t.id === id);
}
